// Chuẩn hóa & Tra cứu hồ sơ lịch sử sức khỏe nhân sự 4 tuần gần nhất
const body = $json.body || $json;

return {
  employeeId: body.employeeId || 'EMP-2026-08',
  employeeName: body.employeeName || 'Trần Thanh Tú',
  employeeEmail: body.employeeEmail || 'tu.tranthanh@company.com',
  department: body.department || 'Phòng Kỹ thuật & AI',
  sentimentScore: Number(body.sentimentScore !== undefined ? body.sentimentScore : -0.65),
  burnoutRisk: body.burnoutRisk || 'HIGH',
  recentSurveysCount: 4,
  avgWeeklyOTHours: 18,
  triggerReason: body.triggerReason || 'Phát hiện rủi ro kiệt sức cao từ khảo sát tuần 40'
};

// Bóc tách kết quả tư vấn từ Google Gemini AI
const inputItem = $input.first().json;
let geminiRaw = '';

if (inputItem?.content?.parts?.[0]?.text) {
  geminiRaw = inputItem.content.parts[0].text;
} else if (inputItem?.content?.text) {
  geminiRaw = inputItem.content.text;
} else if (typeof inputItem?.content === 'string') {
  geminiRaw = inputItem.content;
} else if (typeof inputItem?.text === 'string') {
  geminiRaw = inputItem.text;
}

let parsed = null;
try {
  const jsonMatch = geminiRaw.match(/\{[\s\S]*\}/);
  if (jsonMatch) parsed = JSON.parse(jsonMatch[0]);
} catch (e) {
  parsed = null;
}

const original = $('Tra Cứu & Chuẩn Hóa Lịch Sử Sức Khỏe').first()?.json || {
  employeeName: 'Trần Thanh Tú',
  employeeEmail: 'dang.2006.qt@gmail.com',
  department: 'Phòng Kỹ thuật & AI',
  sentimentScore: -0.2,
  burnoutRisk: 'LOW'
};

let actionType = parsed?.actionType || 'COFFEE_VOUCHER';
let packageTitle = parsed?.packageTitle || 'Gói Phục Hồi Năng Lượng: E-Voucher Highlands & Half-day Rest';
let actionCode = 'ACT_GEMINI_' + Date.now();

// Phân luồng chuẩn xác theo mức độ stress và rủi ro kiệt sức
const score = Number(original.sentimentScore !== undefined ? original.sentimentScore : -0.2);
const risk = (original.burnoutRisk || '').toUpperCase();
const forcedAction = original.actionType || original.body?.actionType;

if (forcedAction && ['COFFEE_VOUCHER', 'COUNSELING_CHAT', 'WORKLOAD_RELIEF'].includes(forcedAction)) {
  actionType = forcedAction;
} else if (score >= -0.3 || risk === 'LOW') {
  // Stress nhẹ (>= -0.3 hoặc rủi ro LOW): Luôn kích hoạt nhánh gửi E-Voucher Cafe
  actionType = 'COFFEE_VOUCHER';
  packageTitle = 'Gói Phục Hồi Năng Lượng: E-Voucher Highlands & Half-day Rest';
} else if (score <= -0.7 || risk === 'HIGH' || risk === 'CRITICAL') {
  // Kiệt sức nặng: Báo HR Lead để 1-on-1 kín đáo
  actionType = 'COUNSELING_CHAT';
  packageTitle = 'Buổi Trò Chuyện Tâm Lý 1-on-1 Bảo Mật với HR Lead';
} else {
  // Quá tải công việc / dự án: Giảm tải sprint & Mindfulness
  actionType = 'WORKLOAD_RELIEF';
  packageTitle = 'Điều Phối Giảm Tải Sprint & Cẩm Nang Mindfulness Chống Burnout';
}

return {
  ...original,
  actionCode,
  actionType,
  packageTitle,
  executedAt: new Date().toISOString()
};

